; count.asm -- chapter 2: numbers in three notations
; generated by gen02.py
        INCLUDE "msx.inc"
        OUTPUT "count.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 1
        ld c, 0
        ld hl, hd
        call puts
        ld c, 17
        ld hl, hd
        call puts
        xor a                   ; the left column: 0, 1, 2 ... 15
        ld b, 3
left:   ld c, 0
        call show
        inc a
        inc b
        cp 16
        jr nz, left
        ld ix, picks            ; the right column, from the table
        ld b, 3
right:  ld c, 17
        ld a, (ix+0)
        call show
        inc ix
        inc b
        ld a, b
        cp 19
        jr nz, right
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; show: A = the number: decimal, space, hexadecimal, space, 8 bits. Keeps A.
show:   push af
        call putdec
        inc c
        pop af
        push af
        call puthex
        inc c
        pop af
        push af
        call fatbits
        pop af
        ret

hd:     db "dec hex bits", 0
picks:  db 16, 17, 31, 32, 63, 64, 100, 127, 128, 129, 170, 192, 200, 240, 254, 255

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret

; putdec: A = a byte taken as unsigned (0-255): three characters, right-aligned
; putsgn: A = a byte taken as signed (-128 to 127): four characters
;         C moves on by 3 or 4. Uses A, DE, HL.
putdec: push bc
        ld d, ' '
        call digits
        pop bc
        ld hl, numbuf + 1
        ld e, 3
        jr pnout
putsgn: push bc
        ld d, ' '
        bit 7, a                ; the top bit is the sign
        jr z, .pos
        neg                     ; two's complement: the size of the number
        ld d, '-'
.pos:   call digits
        pop bc
        ld hl, numbuf
        ld e, 4
pnout:  ld a, (hl)
        call putc
        inc c
        inc hl
        dec e
        jr nz, pnout
        ret

; digits: A (0-255) into numbuf in decimal, right-aligned, D just left of
;         the first digit. Uses A, C, HL.
digits: ld hl, numbuf
        ld (hl), ' '
        inc hl
        ld (hl), ' '
        inc hl
        ld (hl), ' '
        inc hl
        ld (hl), ' '            ; HL: the last character
.next:  ld c, 0                 ; C: A divided by 10
.ten:   cp 10
        jr c, .rest
        sub 10
        inc c
        jr .ten
.rest:  add a, '0'
        ld (hl), a              ; the remainder is this digit
        dec hl
        ld a, c
        or a
        jr nz, .next            ; and the quotient is what is left
        ld (hl), d              ; the sign, or a space
        ret
numbuf  EQU VARS                ; 4 bytes of RAM

; fatbits: A = a byte, drawn as 8 boxes, bit 7 first: a filled box for 1,
;          an empty one for 0. B = row, C = column; C moves on by 8.
;          Uses A. Keeps HL.
fatbits:
        push hl
        ld l, a
        ld h, 8
.bit:   ld a, 1                 ; an empty box ...
        rl l                    ; the next bit, into the carry
        jr nc, .put
        ld a, 2                 ; ... or a filled one
.put:   call putc
        inc c
        dec h
        jr nz, .bit
        pop hl
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
